char *IEC104Stats::getFlowInfo(char *buf, u_int buf_len) {
  if (buf) {
    lock.rdlock(__FILE__, __LINE__);
    snprintf(buf, buf_len - 1, "%s", infobuf);
    lock.unlock(__FILE__, __LINE__);
  }

  return (buf);
}

