bool IEC104Stats::isMonitoringTypeId(u_int16_t tid) {
  return (((tid <= 40) || (tid == 70)) ? true : false);
}

/* *************************************** */

bool IEC104Stats::isCommandTypeId(u_int16_t tid) {
  if (((tid >= 45) && (tid <= 64)) || ((tid >= 100) && (tid <= 107)))
    return (true);
  else
    return (false);
}

