        if (!initial_run) {
          u_int32_t diff = abs(tx_value - (tx_seq_num + 1));

          /* Check for id reset (16 bit only) */
          if (diff != 32768) pkt_lost.tx += diff;
        }
        tx_seq_num = tx_value;

        if (!tx_direction) {
          if (!initial_run) {
            u_int32_t diff = abs(rx_value - rx_seq_num);

            /* Check for id reset (16 bit only) */
